const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const M = nextInt();
    if (M === null) return;
    const N = nextInt();

    const estoque = new Int32Array(M * N);

    for (let i = 0; i < M; i++) {
        for (let j = 0; j < N; j++) {
            estoque[i * N + j] = nextInt();
        }
    }

    const P = nextInt();
    let vendas = 0;

    for (let k = 0; k < P; k++) {
        const I = nextInt() - 1;
        const J = nextInt() - 1;

        const idx = I * N + J;
        if (estoque[idx] > 0) {
            estoque[idx]--;
            vendas++;
        }
    }

    console.log(vendas);
}

main();
